      o: ["כְּתוֹצָאָה מִכָּךְ","לְעֻמַּת זֹאת","כְּמוֹ כֵן","בְּמִלִּים אֲחֵרוֹת"], a: 0, k: "result", d: ["result","contrast","addition","clarify"],
